    menu:SetPoint("TOPLEFT", f.classButton, "BOTTOMLEFT", 0, -2)
    menu:SetSize(170, 24 + (#CLASSES + 1) * 22)
    menu:EnableMouse(true)
    local menuBg = menu:CreateTexture(nil, "BACKGROUND")
    menuBg:SetAllPoints()
    menuBg:SetColorTexture(0.05, 0.04, 0.03, 0.97)
    local menuEdge = menu:CreateTexture(nil, "BORDER")
    menuEdge:SetPoint("TOPLEFT", -1, 1)
    menuEdge:SetPoint("BOTTOMRIGHT", 1, -1)
    menuEdge:SetColorTexture(0.6, 0.45, 0.15, 0.9)
    menuEdge:SetDrawLayer("BACKGROUND", -1)
    menu:Hide()
    menu.rows = {}

    local function Picked()
        if type(settings.planClasses) ~= "table" then settings.planClasses = {} end
        return settings.planClasses
    end
    local function MenuRefresh()
        local set = {}
        for _, c in ipairs(ClassSet()) do set[c] = true end
        for _, row in ipairs(menu.rows) do
            if row.cls then
                row.tick:SetShown(set[row.cls] == true)
                row.text:SetText(ClassName(row.cls) .. (row.cls == PlayerClass() and ("  |cff888888" .. L["(you)"] .. "|r") or ""))
            end
        end
    end
    local function MenuRow(i, label, onClick)
        local row = CreateFrame("Button", nil, menu)
        row:SetHeight(20)
        row:SetPoint("TOPLEFT", 6, -6 - (i - 1) * 22)
        row:SetPoint("TOPRIGHT", -6, -6 - (i - 1) * 22)
        local hl = row:CreateTexture(nil, "HIGHLIGHT")
        hl:SetAllPoints()
        hl:SetColorTexture(1, 0.82, 0.3, 0.15)
        row.tick = row:CreateTexture(nil, "ARTWORK")
        row.tick:SetSize(16, 16)
        row.tick:SetPoint("LEFT", 2, 0)
        row.tick:SetTexture("Interface\\Buttons\\UI-CheckBox-Check")
        row.tick:Hide()
        row.text = row:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
        row.text:SetPoint("LEFT", 22, 0)
        row.text:SetText(label or "")
        row:SetScript("OnClick", onClick)
        menu.rows[#menu.rows + 1] = row
        return row
    end
    for i, cls in ipairs(CLASSES) do
        local row = MenuRow(i, nil, nil)
        row.cls = cls
        row:SetScript("OnClick", function()
            local pick = Picked()
            -- First tick on a fresh list keeps the class shown until now.
            if not next(pick) then
                for _, c in ipairs(ClassSet()) do pick[c] = true end
            end
            pick[cls] = (not pick[cls]) or nil
            settings.planClass = false
            MenuRefresh()
            Refresh()
        end)
    end
    MenuRow(#CLASSES + 1, "|cffffd100" .. L["Only my class"] .. "|r", function()
        wipe(Picked())
        settings.planClass = false
        MenuRefresh()
        Refresh()
    end)
    local hint = menu:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    hint:SetPoint("BOTTOM", 0, 6)
    hint:SetText(L["Tick every class whose gear you wear."])
    f.classButton:SetScript("OnClick", function()
        MenuRefresh()
        menu:SetShown(not menu:IsShown())
    end)
    f:HookScript("OnHide", function() menu:Hide() end)

    -- Slot panel: worn items in character sheet order, and three lists.
    local panel = CreateFrame("Frame", nil, f)
    panel:SetPoint("TOPLEFT", 14, -80)
    panel:SetSize(84, 420)
    f.slotPanel = panel
    f.slotButtons = {}
    local function SlotButton(key, x, y, def, text)
        local b = CreateFrame("Button", nil, panel)
        b:SetSize(36, 36)
        b:SetPoint("TOPLEFT", x, y)
        b.key = key
        if def then
            b.inv, b.slotName = def.inv, def.slot
            b.fallback = "Interface\\PaperDoll\\UI-Backpack-EmptySlot"
            b.icon = b:CreateTexture(nil, "ARTWORK")
            b.icon:SetAllPoints()
        else
            b:SetSize(80, 18)
            local fs = b:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
            fs:SetAllPoints()
            fs:SetText(text)
            local bg = b:CreateTexture(nil, "BACKGROUND")
            bg:SetAllPoints()
            bg:SetColorTexture(1, 1, 1, 0.08)
        end
        b.sel = b:CreateTexture(nil, "OVERLAY")
        b.sel:SetPoint("TOPLEFT", -3, 3)
        b.sel:SetPoint("BOTTOMRIGHT", 3, -3)
        b.sel:SetTexture("Interface\\Buttons\\CheckButtonHilight")
        b.sel:SetBlendMode("ADD")
        b.sel:Hide()
        b:SetHighlightTexture("Interface\\Buttons\\ButtonHilight-Square", "ADD")
        b.badge = b:CreateFontString(nil, "OVERLAY", "NumberFontNormal")
        b.badge:SetPoint("BOTTOMRIGHT", -1, 1)
        b:SetScript("OnClick", function()
            settings.slot = key
            Refresh()
        end)
        b:SetScript("OnEnter", function(self)
            GameTooltip:SetOwner(self, "ANCHOR_LEFT")
            GameTooltip:AddLine(L[SLOT_LABEL[key] or key])
            GameTooltip:Show()
        end)
        b:SetScript("OnLeave", function() GameTooltip:Hide() end)
        f.slotButtons[#f.slotButtons + 1] = b
        return b
    end
    -- Left column head to wrist, right column hands to trinket, weapons below.
    for i = 1, 6 do SlotButton(SLOT_BUTTONS[i].key, 0, -(i - 1) * 40, SLOT_BUTTONS[i]) end
    for i = 7, 12 do SlotButton(SLOT_BUTTONS[i].key, 42, -(i - 7) * 40, SLOT_BUTTONS[i]) end
    for i = 13, 15 do SlotButton(SLOT_BUTTONS[i].key, (i - 13) * 28 - 2, -246, SLOT_BUTTONS[i]):SetSize(26, 26) end
    SlotButton("bags", 0, -282, nil, L["Bags"])
    SlotButton("all", 0, -304, nil, L["Best for me"])
    SlotButton("wish", 0, -326, nil, L["Wishlist"])

    f.status = f:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    f.status:SetPoint("TOPLEFT", f.summary, "BOTTOMLEFT", 0, -6)
    f.status:SetPoint("RIGHT", f, "RIGHT", -18, 0)
    f.status:SetJustifyH("LEFT")

    local credit = f:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    credit:SetPoint("BOTTOMLEFT", 16, 12)
    credit:SetPoint("BOTTOMRIGHT", -16, 12)
    credit:SetJustifyH("LEFT")
    credit:SetText("")

    local scroll = CreateFrame("ScrollFrame", nil, f, "UIPanelScrollFrameTemplate")
    scroll:SetPoint("TOPLEFT", 14, -80)
    scroll:SetPoint("BOTTOMRIGHT", -32, 30)
    local content = CreateFrame("Frame", nil, scroll)
    content:SetSize(W - 50, 1)
    scroll:SetScrollChild(content)
    scroll:SetScript("OnSizeChanged", function(_, w) content:SetWidth(w) end)
    f.content = content
    f.scroll = scroll

    f.empty = f:CreateFontString(nil, "OVERLAY", "GameFontDisable")
    f.empty:SetPoint("CENTER")
    f.empty:SetWidth(W - 100)
    f.empty:SetText(L["Nothing listed for your level here. Press Show all."])

    f:SetScript("OnShow", function()
        if settings.mode == "gear" then ScanJournal() end
        Refresh()
    end)
    window = f
end

local function Toggle()
    if not running then
        print(PREFIX .. L["switched off. Switch it on in OxedHub's Modules page first."])
        return
    end
    BuildWindow()
    window:SetShown(not window:IsShown())
end

