-- ── Quest scanner (/oxfind scan) ────────────────────────────────────────────
-- Asks the server for one quest at a time by number and writes down its
-- title and item rewards in settings.scanned[questID]. Slow on purpose
-- (about 4 a second, one request in flight) so the server never sees a burst.
-- .outsource/questscan/export.js turns the result into LevelingFindsRewards.lua.

local scan = { on = false }
local SCAN_GAP, SCAN_WAIT = 0.25, 2

local function ItemIDFromInfo(fn, i, questID)
    local ok, _, _, _, _, _, itemID = pcall(fn, i, questID)
    return (ok and type(itemID) == "number" and itemID > 0) and itemID or nil
end

local function ReadScannedQuest(questID)
    if not (C_QuestLog and C_QuestLog.GetTitleForQuestID) then return end
    local ok, title = pcall(C_QuestLog.GetTitleForQuestID, questID)
    if not ok or type(title) ~= "string" or title == "" or Secret(title) then return end
    local choices, given = {}, {}
    if GetNumQuestLogChoices and GetQuestLogChoiceInfo then
        local okN, n = pcall(GetNumQuestLogChoices, questID, false)
        for i = 1, (okN and type(n) == "number") and n or 0 do
            choices[#choices + 1] = ItemIDFromInfo(GetQuestLogChoiceInfo, i, questID)
        end
    end
    if GetNumQuestLogRewards and GetQuestLogRewardInfo then
        local okN, n = pcall(GetNumQuestLogRewards, questID)
        for i = 1, (okN and type(n) == "number") and n or 0 do
            given[#given + 1] = ItemIDFromInfo(GetQuestLogRewardInfo, i, questID)
        end
    end
    settings.scanned = settings.scanned or {}
    settings.scanned[questID] = { t = title, c = choices, r = given }
    scan.found = scan.found + 1
    if #choices > 0 or #given > 0 then
        scan.items = scan.items + 1
        settings.rewards[title] = settings.rewards[title] or { c = choices, r = given }
    end
end

-- Rewards come in after the title: ask for them, then wait until the client
-- says it has them (HaveQuestRewardData) or give up after a few seconds.
-- The first scan read too early and missed most quests' items.
local function AskRewards(questID)
    if C_TaskQuest and C_TaskQuest.RequestPreloadRewardData then
        pcall(C_TaskQuest.RequestPreloadRewardData, questID)
    end
end

local function HaveRewards(questID)
    if not HaveQuestRewardData then return nil end
    local ok, v = pcall(HaveQuestRewardData, questID)
    if not ok or Secret(v) then return nil end
    return v and true or false
end

local REWARD_WAIT, REWARD_STEP = 4, 0.25

local ScanNext
local function ScanDone(questID, loaded)
    if not scan.on or scan.waiting ~= questID then return end
    scan.waiting = nil
    if not loaded then C_Timer.After(SCAN_GAP, ScanNext) return end
    AskRewards(questID)
    local waited = 0
    local function Try()
        if not scan.on then return end
        local have = HaveRewards(questID)
        if have == false and waited < REWARD_WAIT then
            waited = waited + REWARD_STEP
            C_Timer.After(REWARD_STEP, Try)
            return
        end
        if have then scan.ready = (scan.ready or 0) + 1 end
        ReadScannedQuest(questID)
        C_Timer.After(SCAN_GAP, ScanNext)
    end
    C_Timer.After(REWARD_STEP, Try)
end

ScanNext = function()
    if not scan.on then return end
    local id
    if scan.list then
        -- /oxfind rescan: only the quests that came back without items.
        id = scan.list[scan.idx]
        if not id then
            scan.on = false
            settings.rescanIdx = nil
            print(PREFIX .. (L["Rescan finished: %d quests checked, %d now with item rewards."]):format(
                #scan.list, scan.items))
            return
        end
        scan.idx = scan.idx + 1
        settings.rescanIdx = scan.idx
        if scan.idx % 100 == 0 then
            print(PREFIX .. (L["Rescanning %d of %d: %d with item rewards so far."]):format(
                scan.idx, #scan.list, scan.items))
        end
    else
        id = scan.id
        if id > scan.to then
            scan.on = false
            print(PREFIX .. (L["Scan finished at quest %d: %d quests found, %d with item rewards."]):format(
                scan.to, scan.found, scan.items))
            return
        end
        scan.id = id + 1
        settings.scanPos = scan.id
        if (id - scan.from) % 250 == 0 and id ~= scan.from then
            print(PREFIX .. (L["Scanning quest %d of %d: %d found, %d with item rewards."]):format(
                id, scan.to, scan.found, scan.items))
        end
    end
    scan.waiting = id
    pcall(C_QuestLog.RequestLoadQuestByID, id)
    -- Quests the server never answers for: move on after a while.
    C_Timer.After(SCAN_WAIT, function() ScanDone(id, true) end)
end

local function ScanCommand(args)
    if args == "stop" then
        scan.on = false
        print(PREFIX .. (L["Scan stopped at quest %d. /oxfind scan continues from there."]):format(settings.scanPos or 1))
        return
    end
    if not (C_QuestLog and C_QuestLog.RequestLoadQuestByID and C_QuestLog.GetTitleForQuestID) then
        print(PREFIX .. L["This client cannot load quests by number."])
        return
    end
    if not running then
        print(PREFIX .. L["switched off. Switch it on in OxedHub's Modules page first."])
        return
    end
    if args == "rescan" then
        local list = {}
        for id, q in pairs(settings.scanned or {}) do
            if type(q) == "table" and q.t and #(q.c or {}) == 0 and #(q.r or {}) == 0 then list[#list + 1] = id end
        end
        table.sort(list)
        scan.list, scan.idx = list, math.min(settings.rescanIdx or 1, #list + 1)
        scan.found, scan.items, scan.ready, scan.on = 0, 0, 0, true
        print(PREFIX .. (L["Rescanning %d quests that showed no items, from number %d. /oxfind scan stop to stop."]):format(
            #list, scan.idx))
        ScanNext()
        return
    end
    scan.list = nil
    local from, to = args:match("^(%d+)%s+(%d+)$")
    from, to = tonumber(from), tonumber(to)
    if not from then
        from, to = settings.scanPos or 1, 15000
    end
    scan.from, scan.to, scan.id = from, math.max(from, to), from
    scan.found, scan.items, scan.on = 0, 0, true
    settings.scanned = settings.scanned or {}
    print(PREFIX .. (L["Scanning quests %d to %d, about 4 a second. /oxfind scan stop to stop."]):format(from, scan.to))
    ScanNext()
end

SLASH_OXEDLEVELFINDS1 = "/oxfind"
SLASH_OXEDLEVELFINDS2 = "/levelfinds"
SlashCmdList.OXEDLEVELFINDS = function(msg)
    msg = (msg or ""):lower():match("^%s*(.-)%s*$")
    local scanArgs = msg:match("^scan%s*(.*)$")
    if msg == "rescan" then ScanCommand("rescan")
    elseif scanArgs then ScanCommand(scanArgs)
    elseif msg == "options" or msg == "config" then ShowOptions()
    else Toggle() end
end

-- ── Events ──────────────────────────────────────────────────────────────────

local refreshQueued = false
local function QueueRefresh(delay)
    if not running or refreshQueued or not (window and window:IsShown()) then return end
    refreshQueued = true
    C_Timer.After(delay or 0.3, function()
        refreshQueued = false
        if running then Refresh() end
    end)
end

local logQueued = false
local function QueueLogCapture()
    if logQueued then return end
    logQueued = true
    C_Timer.After(1, function()
        logQueued = false
        if running then CaptureQuestLog() QueueRefresh(0) end
    end)
end

events:SetScript("OnEvent", function(_, event, a1, a2)
    if not running then return end
    if event == "QUEST_DATA_LOAD_RESULT" then
        if scan.on and a1 == scan.waiting then ScanDone(a1, a2 and true or false) end
        return
    end
    if event == "QUEST_DETAIL" or event == "QUEST_COMPLETE" then
        CaptureGossipQuest()
    elseif event == "QUEST_ACCEPTED" or event == "PLAYER_ENTERING_WORLD" then
        QueueLogCapture()
    end
    QueueRefresh(0.3)
end)

local EVENTS = { "GET_ITEM_INFO_RECEIVED", "PLAYER_LEVEL_UP", "ZONE_CHANGED_NEW_AREA", "QUEST_DETAIL",
                 "QUEST_COMPLETE", "QUEST_ACCEPTED", "PLAYER_ENTERING_WORLD", "PLAYER_EQUIPMENT_CHANGED",
                 "QUEST_DATA_LOAD_RESULT" }

-- Distances change as the player moves: re-sort every few seconds while open.
local ticker
local function Start()
    if running then return end
    running = true
    for _, e in ipairs(EVENTS) do pcall(events.RegisterEvent, events, e) end
    if C_Timer.NewTicker then
        ticker = C_Timer.NewTicker(5, function() QueueRefresh(0) end)
    end
    QueueLogCapture()
end

local function Stop()
    running = false
    events:UnregisterAllEvents()
    if ticker then ticker:Cancel() ticker = nil end
    if window then window:Hide() end
end

-- ── Login ───────────────────────────────────────────────────────────────────

MinimapIcon = function()
    if minimapIcon or not settings then return minimapIcon end
    local API = OxedHub.ModuleAPI
    minimapIcon = API and API.MinimapButton and API:MinimapButton({
        key = "levelingfinds", label = L["Leveling Finds"], icon = "Interface\\Icons\\INV_Misc_Map_01", config = settings,
        hint = L["Click: the list. Right-click: options."],
        onClick = function(mouse)
            if mouse == "RightButton" then ShowOptions() else Toggle() end
        end,
    })
    return minimapIcon
end

local loginFrame = CreateFrame("Frame")
loginFrame:RegisterEvent("PLAYER_LOGIN")
loginFrame:SetScript("OnEvent", function(self)
    self:UnregisterEvent("PLAYER_LOGIN")
    -- Forever's quests and zones; nothing to show on the main game.
    if OxedHub.IsMainline then return end
    OxedHubDB = OxedHubDB or {}
    OxedHubDB.modules = OxedHubDB.modules or {}
    local config = OxedHubDB.modules.levelingfinds
    if type(config) ~= "table" then
        config = {}
        OxedHubDB.modules.levelingfinds = config
    end
    for key, value in pairs(DEFAULTS) do
        if config[key] == nil then config[key] = value end
    end
    if type(config.rewards) ~= "table" then config.rewards = {} end
    if type(config.wish) ~= "table" then config.wish = {} end
    if type(config.planClasses) ~= "table" then config.planClasses = {} end
    if config.mode ~= "gear" and config.mode ~= "quests" and config.mode ~= "dungeons" then config.mode = "gear" end
    settings = config

    if not OxedHub.ModuleAPI then return end
    OxedHub.ModuleAPI:Register({
        id       = "levelingfinds",
        name     = "Leveling Finds",
        version  = "2.6.0",
        updated  = 20261107.995, -- pick several classes for gear
        author   = "Oxed",
        category = "quests",
        keywords = { "leveling", "levelling", "quest", "dungeon", "loot", "map", "forever", "mapgenie", "find" },
        desc     = "Quests and dungeons for your level, nearest first, with a map pin, and the gear they give.",
        icon     = "Interface\\Icons\\INV_Misc_Map_01",
        defaults = DEFAULTS,
        quick = {
            { text = L["Show or hide"], func = function() Toggle() end },
        },
        OnOptionsShow = function() ShowOptions() end,
        OnEnable = function(_, cfg)
            settings = cfg
            if type(settings.rewards) ~= "table" then settings.rewards = {} end
            if type(settings.wish) ~= "table" then settings.wish = {} end
            if type(settings.planClasses) ~= "table" then settings.planClasses = {} end
            local icon = MinimapIcon()
            if icon then icon:Apply(true) end
            Start()
        end,
        OnDisable = function()
            if minimapIcon then minimapIcon:Apply(false) end
            Stop()
        end,
    })
end)
